package com.huy.enterprise.company; import com.huy.enterprise.common.BaseEntity; import com.huy.enterprise.common.enums.RecordStatus; import jakarta.persistence.*; import lombok.*; @Getter @Setter @Entity @Table(name="companies") public class Company extends BaseEntity {@Column(nullable=false) private String name; @Column(name="tax_code",unique=true,length=100) private String taxCode; private String email; private String phone; private String address; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private RecordStatus status=RecordStatus.ACTIVE;}
